1	// Bakes authored terrain materials into isometric chunk textures. Materials
2	// are 512² periodic textures covering 4×4 tiles (docs/asset-pipeline.md), so the
3	// projection is applied at draw time and every chunk tiles seamlessly.
4	import {Texture,Mesh,MeshGeometry} from 'pixi.js';
5	import type {GameMap,Rect} from '../runtime';
6	import {HALF_H,HALF_W,LEVEL_PX} from './iso';
7	import type {ArtLibrary} from './art';
8	import {MATERIALS,materialFor,heightAt,terrainAt,type Material} from './terrain-materials';
9	import {TerrainSurface,projectSurfaceVertex,compareSurfaceTriangles,surfaceFogOpacity,type SurfaceTriangle} from './terrain-surface';
10	export {materialFor,heightAt,terrainAt} from './terrain-materials';
11	
12	/** Cached opaque ground and matching fog geometry. The caller interleaves these
13	 * by ground depth with actors; owning chunk textures are released separately. */
14	export interface TerrainFragment {
15	 mesh:Mesh;fog:Mesh;triangles:readonly SurfaceTriangle[];depth:number;bounds:Readonly<Rect>;
16	 setFog(visible:readonly boolean[],explored:readonly boolean[]):void;
17	 setVisible(visible:boolean):void;
18	 dispose():void;
19	}
20	
21	export const CHUNK=16;
22	const BLEED=2;
23	/** In-map tiles whose closed square contains this ground point: four at a
24	 * corner, two on an edge, one inside. The point's fog is the most-fogged of
25	 * them, so every triangle sharing the point sees the same value and fog stays
26	 * seamless across fragments and chunks. Off-map ground adds nothing. */
27	function pointFogTiles(x:number,y:number,width:number,height:number){
28	 const tx=x/1000,ty=y/1000,x0=Math.max(0,Number.isInteger(tx)?tx-1:Math.floor(tx)),x1=Math.min(width-1,Math.floor(tx)),y0=Math.max(0,Number.isInteger(ty)?ty-1:Math.floor(ty)),y1=Math.min(height-1,Math.floor(ty));
29	 const tiles:number[]=[];
30	 for(let j=y0;j<=y1;j++)for(let i=x0;i<=x1;i++)tiles.push(j*width+i);
31	 return tiles;
32	}
33	const tileFogOpacity=(tile:number,visible:readonly boolean[],explored:readonly boolean[])=>visible[tile]?0:explored[tile]?175:255;
34	const indexArray=(values:readonly number[])=>values.every(n=>n<65536)?new Uint16Array(values):new Uint32Array(values);
35	/** Immutable fog topology for one fragment. `fogTiles` lists every tile its fog
36	 * reads: each triangle's tile and neighbour, and every tile touching each vertex.
37	 * Vertices at the same ground point share one tile run. Construction Maps, lists
38	 * and the `slot` closure live only in this call's scope, so a fragment's runtime
39	 * closures capture the returned typed arrays and nothing else from here.
40	 * `fogFanCorners` holds each top triangle's four tile-corner points (NW, NE, SE,
41	 * SW), keyed by ground x,y, because a fan's four triangles fall into two depth
42	 * fragments; face triangles hold unused zeros. */
43	export function fogTopology(triangles:readonly SurfaceTriangle[],width:number,height:number){
44	 const slotOf=new Map<number,number>(),pointOf=new Map<string,number>(),tileList:number[]=[],pointStart:number[]=[0],pointSlots:number[]=[],vertexPoints:number[]=[],fanCorners:number[]=[];
45	 const slot=(tile:number)=>{let s=slotOf.get(tile);if(s===undefined){s=tileList.length;slotOf.set(tile,s);tileList.push(tile)}return s};
46	 const pointAt=(x:number,y:number)=>{
47	  const key=`${x},${y}`;let point=pointOf.get(key);
48	  if(point===undefined){point=pointStart.length-1;pointOf.set(key,point);for(const tile of pointFogTiles(x,y,width,height))pointSlots.push(slot(tile));pointStart.push(pointSlots.length)}
49	  return point;
50	 };
51	 for(const triangle of triangles){
52	  slot(triangle.tile);if(triangle.neighbor!==undefined)slot(triangle.neighbor);
53	  for(const v of triangle.vertices)vertexPoints.push(pointAt(v.x,v.y));
54	  if(triangle.kind==='top'){const x=triangle.tile%width,y=Math.floor(triangle.tile/width);for(const [dx,dy] of [[0,0],[1,0],[1,1],[0,1]])fanCorners.push(pointAt((x+dx)*1000,(y+dy)*1000))}
55	  else fanCorners.push(0,0,0,0);
56	 }
57	 return {fogTiles:Int32Array.from(tileList),fogPoints:indexArray(vertexPoints),fogPointStart:indexArray(pointStart),fogPointSlots:indexArray(pointSlots),fogFanCorners:indexArray(fanCorners)};
58	}
59	export type FogTopology=ReturnType<typeof fogTopology>;
60	/** Fan-centre ceiling: half of unknown, so boundary ground stays readable. */
61	export const FOG_FAN_CENTRE_CAP=128;
62	/** Writes three vertex alphas per triangle into `out` and reports whether any
63	 * is non-zero. `opacity[k]` is the current opacity of `fogTiles[k]`.
64	 * Explored (175) and unknown (255) triangles keep one constant opacity on all
65	 * three vertices. Only visible (0) triangles feather: each corner takes the
66	 * darkest tile touching that ground point, and a top fan's centre is raised to
67	 * the mean of its tile's four corners, capped at FOG_FAN_CENTRE_CAP. On a
68	 * straight boundary that mean makes all four fan triangles coplanar, so no
69	 * bright crease runs from the centre to the corners; a centre is never lowered. */
70	export function fogVertexAlphas(triangles:readonly SurfaceTriangle[],topology:FogTopology,opacity:ArrayLike<number>,visible:readonly boolean[],explored:readonly boolean[],out:Float32Array):boolean{
71	 const {fogPoints,fogPointStart,fogPointSlots,fogFanCorners}=topology;
72	 const pointAlpha=(point:number)=>{let alpha=0;for(let s=fogPointStart[point];s<fogPointStart[point+1];s++)alpha=Math.max(alpha,opacity[fogPointSlots[s]]);return alpha};
73	 let any=false;
74	 for(let i=0;i<triangles.length;i++){
75	  const base=surfaceFogOpacity(triangles[i],visible,explored);let centre=0;
76	  if(base===0&&triangles[i].kind==='top'){let sum=0;for(let c=0;c<4;c++)sum+=pointAlpha(fogFanCorners[i*4+c]);centre=Math.min(FOG_FAN_CENTRE_CAP,sum/4)}
77	  for(let j=0;j<3;j++){
78	   let alpha=base;
79	   if(base===0){alpha=pointAlpha(fogPoints[i*3+j]);if(j===0)alpha=Math.max(alpha,centre)}
80	   out[i*3+j]=alpha;any ||= alpha!==0;
81	  }
82	 }
83	 return any;
84	}
85	/** Fallback painted colours if a material image is missing (never silently blank). */
86	const FLAT:Record<Material,string>={sand:'#b59a6a',packed_earth:'#8f7852',gravel_wash:'#998c72',scrub_ground:'#7c7448',gravel:'#8a8272',rubble_ground:'#6f675c',asphalt:'#4a4843',shallow_water:'#64847b',deep_water:'#305e64',coast_sand:'#cbbb8e',ramp:'#937c59'};
87	
88	/** Shared read-only palette; each minimap sample still returns its own RGB tuple. */
89	const MINIMAP_BASE:Readonly<Record<string,readonly [number,number,number]>>={open:[128,110,76],road:[74,72,66],rubble:[98,90,80],cover:[104,100,62],water:[44,62,60],cliff:[70,62,50],blocked:[58,52,44],ramp:[120,102,72]};
90	
91	export class TerrainBaker {
92	 private patterns=new Map<string,HTMLImageElement|undefined>();
93	 private faceTextures=new Map<string,Texture>();private fogRamp?:Texture;
94	 constructor(private readonly map:GameMap,private readonly art:ArtLibrary,readonly resolution=1){}
95	 async load(){await Promise.all([...MATERIALS,'ground_macro','road_asphalt_decal','cliff_face_tier1','cliff_face_tier2'].map(async m=>{try{this.patterns.set(m,await this.art.terrain(m))}catch{this.patterns.set(m,undefined)}}))}
96	 chunkOrigin(cx:number,cy:number){const x0=cx*CHUNK,y0=cy*CHUNK;return {x:(x0-(y0+CHUNK))*HALF_W-BLEED,y:(x0+y0)*HALF_H-BLEED}}
97	 get chunksX(){return Math.ceil(this.map.width/CHUNK)}
98	 get chunksY(){return Math.ceil(this.map.height/CHUNK)}
99	 /** Projected envelope of the chunk's owned geometry, including any public
100	  * height from zero through maxHeight. Partial edge chunks use their true tile
101	  * extent. Texture bleed cannot extend the triangle-clipped geometry. */
102	 chunkBounds(cx:number,cy:number,maxHeight:number):Rect{
103	  const x0=cx*CHUNK,y0=cy*CHUNK,x1=Math.min(x0+CHUNK,this.map.width),y1=Math.min(y0+CHUNK,this.map.height);
104	  return {left:(x0-y1)*HALF_W,top:(x0+y0)*HALF_H-maxHeight*LEVEL_PX,right:(x1-y0)*HALF_W,bottom:(x1+y1)*HALF_H};
105	 }
106	 /** Returns a texture whose top-left sits at chunkOrigin(cx,cy) in world px. */
107	 bake(cx:number,cy:number,raised=false):Texture{
108	  const r=this.resolution,W=CHUNK*2*HALF_W+2*BLEED,H=CHUNK*2*HALF_H+4*LEVEL_PX+2*BLEED;
109	  const canvas=document.createElement('canvas');canvas.width=Math.ceil(W*r);canvas.height=Math.ceil(H*r);
110	  const ctx=canvas.getContext('2d')!;const x0=cx*CHUNK,y0=cy*CHUNK,origin=this.chunkOrigin(cx,cy);
111	  // iso transform: tile (x,y) → px, relative to this chunk's origin
112	  const iso=(c:CanvasRenderingContext2D)=>c.setTransform(HALF_W*r,HALF_H*r,-HALF_W*r,HALF_H*r,-origin.x*r,-origin.y*r);
113	  const used=new Set<Material>();
114	  for(let y=y0-1;y<=y0+CHUNK;y++)for(let x=x0-1;x<=x0+CHUNK;x++)if(x>=0&&y>=0&&x<this.map.width&&y<this.map.height)used.add(materialFor(this.map,x,y));
115	  // Base: dominant ground, then each material through a bilinear-softened tile mask.
116	  const order=MATERIALS.filter(m=>used.has(m));
117	  for(const [i,m] of order.entries()){
118	   const layer=document.createElement('canvas');layer.width=canvas.width;layer.height=canvas.height;const lc=layer.getContext('2d')!;
119	   iso(lc);this.fillMaterial(lc,m,x0-1,y0-1,CHUNK+2);
120	   if(i>0){
121	    const mask=document.createElement('canvas');mask.width=CHUNK+4;mask.height=CHUNK+4;const mc=mask.getContext('2d')!;
122	    const img=mc.createImageData(CHUNK+4,CHUNK+4);
123	    for(let ty=0;ty<CHUNK+4;ty++)for(let tx=0;tx<CHUNK+4;tx++){const x=x0-2+tx,y=y0-2+ty;const on=x>=0&&y>=0&&x<this.map.width&&y<this.map.height&&materialFor(this.map,x,y)===m;img.data[(ty*(CHUNK+4)+tx)*4+3]=on?255:0}
124	    mc.putImageData(img,0,0);
125	    lc.globalCompositeOperation='destination-in';lc.imageSmoothingEnabled=true;lc.imageSmoothingQuality='high';
126	    // mask pixel centre = tile centre, so offset by −1.5 tiles
127	    lc.drawImage(mask,x0-2.5+0.5,y0-2.5+0.5,CHUNK+4,CHUNK+4);
128	   }
129	   ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(layer,0,0);
130	  }
131	  iso(ctx);
132	  const macro=this.patterns.get('ground_macro');
133	  if(macro){
134	   const pattern=ctx.createPattern(macro,'repeat')!;pattern.setTransform(new DOMMatrix([32/macro.naturalWidth,0,0,32/macro.naturalHeight,0,0]));
135	   // The authored 128 grey is neutral, so overlay preserves the original base
136	   // luminance instead of multiplying every pixel down to half brightness. Kept
137	   // subtle: stronger macro reads as stains on flat sand and hides infantry.
138	   ctx.globalCompositeOperation='overlay';ctx.globalAlpha=.35;ctx.fillStyle=pattern;ctx.fillRect(x0-1,y0-1,CHUNK+2,CHUNK+2);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
139	  }
140	  // Elevation: plateaus lighten, escarpment faces fall toward the camera.
141	  for(let y=Math.max(0,y0-1);y<=y0+CHUNK&&y<this.map.height;y++)for(let x=Math.max(0,x0-1);x<=x0+CHUNK&&x<this.map.width;x++){
142	   const h=heightAt(this.map,x,y),terrain=terrainAt(this.map,x,y);
143	   if(h>0){ctx.fillStyle=`rgba(255,236,196,${Math.min(0.2,h*0.05)})`;ctx.fillRect(x,y,1,1)}
144	   if(terrain==='cliff'||terrain==='blocked'){ctx.fillStyle='rgba(40,34,26,0.45)';ctx.fillRect(x,y,1,1)}
145	   if(terrain==='road')this.roadEdges(ctx,x,y);
146	   for(const [dx,dy] of (raised?[]:[[1,0],[0,1]]) as Array<readonly [number,number]>){
147	    const hn=heightAt(this.map,x+dx,y+dy);if(hn>=h)continue;const drop=(h-hn)*LEVEL_PX/HALF_H;
148	    ctx.fillStyle='rgba(28,22,16,0.55)';
149	    if(dx)ctx.fillRect(x+1,y,Math.min(0.6,drop*0.35),1);else ctx.fillRect(x,y+1,1,Math.min(0.6,drop*0.35));
150	    ctx.strokeStyle='rgba(255,236,196,0.35)';ctx.lineWidth=0.05;ctx.beginPath();if(dx){ctx.moveTo(x+1,y);ctx.lineTo(x+1,y+1)}else{ctx.moveTo(x,y+1);ctx.lineTo(x+1,y+1)}ctx.stroke();
151	   }
152	  }
153	  // Map edge: dark bevel so the playable diamond reads as a board.
154	  ctx.fillStyle='rgba(0,0,0,0.35)';
155	  if(x0+CHUNK>=this.map.width)ctx.fillRect(this.map.width-0.15,y0,0.15,CHUNK);
156	  if(y0+CHUNK>=this.map.height)ctx.fillRect(x0,this.map.height-0.15,CHUNK,0.15);
157	  const texture=Texture.from(canvas);texture.source.scaleMode='linear';
158	  return texture;
159	 }
160	 /** Two triangles own exactly this chunk's map tiles. The padded texture stays
161	  * opaque across shared edges; alpha-clipped rectangular sprites create seams
162	  * and camera-order-dependent overlaps when neighbouring chunks are blended. */
163	 mesh(cx:number,cy:number,texture:Texture){
164	  const x0=cx*CHUNK,y0=cy*CHUNK,x1=Math.min(x0+CHUNK,this.map.width),y1=Math.min(y0+CHUNK,this.map.height),origin=this.chunkOrigin(cx,cy);
165	  const corners=[[x0,y0],[x1,y0],[x1,y1],[x0,y1]],positions=new Float32Array(corners.flatMap(([x,y])=>[(x-y)*HALF_W-origin.x,(x+y)*HALF_H-origin.y]));
166	  const uvs=new Float32Array(positions.map((value,i)=>value*this.resolution/(i%2?texture.height:texture.width)));
167	  const mesh=new Mesh({texture,geometry:new MeshGeometry({positions,uvs,indices:new Uint32Array([0,1,2,0,2,3])})});mesh.position.set(origin.x,origin.y);return mesh;
168	 }
169	 /** Additive stage-2 API. Flat product mesh stays available until projection,
170	  * actor anchors, picking and fog are switched together by the integration owner. */
171	 surfaceFragments(cx:number,cy:number,texture:Texture,surface:TerrainSurface):TerrainFragment[]{
172	  const x0=cx*CHUNK,y0=cy*CHUNK,x1=Math.min(x0+CHUNK,this.map.width),y1=Math.min(y0+CHUNK,this.map.height),origin=this.chunkOrigin(cx,cy);
173	  if(x0<0||y0<0||x0>=this.map.width||y0>=this.map.height||surface.width!==this.map.width||surface.height!==this.map.height)throw new Error('Invalid surface chunk');
174	  const groups=new Map<string,SurfaceTriangle[]>();
175	  for(const triangle of surface.triangles({left:x0*1000,top:y0*1000,right:x1*1000,bottom:y1*1000})){
176	   if(!triangle.frontFacing)continue;
177	   const tier=triangle.kind==='face'&&Math.max(...triangle.vertices.map(v=>v.height))-Math.min(...triangle.vertices.map(v=>v.height))>1?'cliff_face_tier2':'cliff_face_tier1';
178	   const key=`${triangle.depth.toFixed(6)}:${triangle.kind}:${tier}`;let group=groups.get(key);if(!group){group=[];groups.set(key,group)}group.push(triangle);
179	  }
180	  if(!this.fogRamp){
181	   // Texel i has alpha i. Constant-u triangles sample their own texel; clamped
182	   // addressing keeps extrapolated u on visible triangles at or above texel 0.
183	   const canvas=document.createElement('canvas');canvas.width=256;canvas.height=1;const ctx=canvas.getContext('2d')!,pixels=ctx.createImageData(256,1);
184	   for(let alpha=0;alpha<256;alpha++)pixels.data.set([8,9,7,alpha],alpha*4);ctx.putImageData(pixels,0,0);
185	   this.fogRamp=Texture.from(canvas);this.fogRamp.source.scaleMode='linear';
186	  }
187	  return [...groups.values()].sort((a,b)=>compareSurfaceTriangles(a[0],b[0])).map(triangles=>{
188	   // Small depth fragments stay on Pixi's batch path; explicit batch mode also
189	   // supports a long diagonal without falling out at the 100-vertex auto limit.
190	   triangles.sort(compareSurfaceTriangles);const first=triangles[0],positions:number[]=[],uvs:number[]=[],indices:number[]=[],fogUVs=new Float32Array(triangles.length*6);
191	   const face=first.kind==='face',tier=Math.max(...first.vertices.map(v=>v.height))-Math.min(...first.vertices.map(v=>v.height))>1?'cliff_face_tier2':'cliff_face_tier1';
192	   for(const triangle of triangles)for(const vertex of triangle.vertices){
193	    const p=projectSurfaceVertex(vertex),flatX=(vertex.x-vertex.y)/1000*HALF_W,flatY=(vertex.x+vertex.y)/1000*HALF_H;
194	    positions.push(p.x-origin.x,p.y-origin.y);indices.push(indices.length);
195	    if(face)uvs.push((vertex.x+vertex.y)/4000,(4-vertex.height)/4);
196	    else uvs.push((flatX-origin.x)*this.resolution/texture.width,(flatY-origin.y)*this.resolution/texture.height);
197	   }
198	   let material=texture;
199	   if(face){
200	    let cached=this.faceTextures.get(tier);if(!cached){const image=this.patterns.get(tier);if(image){cached=Texture.from(image);cached.source.addressMode='repeat';cached.source.scaleMode='linear'}else{
201	     const canvas=document.createElement('canvas');canvas.width=canvas.height=2;const ctx=canvas.getContext('2d')!;ctx.fillStyle='#665342';ctx.fillRect(0,0,2,2);cached=Texture.from(canvas);
202	    }this.faceTextures.set(tier,cached)}material=cached;
203	   }
204	   const geometry=new MeshGeometry({positions:new Float32Array(positions),uvs:new Float32Array(uvs),indices:new Uint32Array(indices)});geometry.batchMode='batch';
205	   const mesh=new Mesh({texture:material,geometry});mesh.position.set(origin.x,origin.y);mesh.zIndex=first.depth;
206	   if(face)mesh.tint=first.vertices[0].x===first.vertices[1].x&&first.vertices[1].x===first.vertices[2].x?0xb8b09f:0x999183;
207	   const fogGeometry=new MeshGeometry({positions:new Float32Array(positions),uvs:fogUVs,indices:new Uint32Array(indices)});fogGeometry.batchMode='batch';
208	   const fog=new Mesh({texture:this.fogRamp!,geometry:fogGeometry});fog.position.copyFrom(mesh.position);fog.zIndex=first.depth+.0001;
209	   // Exact projected geometry bounds include every raised top and cliff face.
210	   // They cull only fragments wholly outside the viewport, never hidden-world data.
211	   const bounds:Rect={left:Infinity,top:Infinity,right:-Infinity,bottom:-Infinity};
212	   for(let i=0;i<positions.length;i+=2){bounds.left=Math.min(bounds.left,positions[i]+origin.x);bounds.right=Math.max(bounds.right,positions[i]+origin.x);bounds.top=Math.min(bounds.top,positions[i+1]+origin.y);bounds.bottom=Math.max(bounds.bottom,positions[i+1]+origin.y)}
213	   // Built once in module scope; only its typed arrays enter this closure scope.
214	   const topology=fogTopology(triangles,this.map.width,this.map.height),{fogTiles}=topology;
215	   // Opacity of each fog tile at the last recompute; 1 is never a tile opacity.
216	   const lastOpacity=new Uint8Array(fogTiles.length).fill(1),alphas=new Float32Array(triangles.length*3);
217	   let shown=true,fogNeeded=true;
218	   const setFog=(visible:readonly boolean[],explored:readonly boolean[])=>{
219	    // Read the CURRENT value of every dependency, never array identity or tick.
220	    // If none changed, the retained UVs and fogNeeded equal what a recompute
221	    // would produce, and the GPU buffer already holds them.
222	    let changed=false;
223	    for(let k=0;k<fogTiles.length;k++){const opacity=tileFogOpacity(fogTiles[k],visible,explored);if(opacity!==lastOpacity[k]){lastOpacity[k]=opacity;changed=true}}
224	    if(!changed){fog.visible=shown&&fogNeeded;return}
225	    // Explored (175) and unknown (255) triangles keep one constant old opacity on
226	    // all three vertices, so no sample can differ from before: antialiased MSAA
227	    // evaluates Pixi's non-centroid vUV at the pixel centre, which may lie outside
228	    // the triangle, and a varying vUV would then extrapolate below every vertex.
229	    // Only visible (0) triangles feather (see fogVertexAlphas); any extrapolation
230	    // below 0 clamps to texel 0. The explored/unknown boundary therefore stays
231	    // hard, while fog softens only into currently visible ground, and all-clear
232	    // triangles stay exactly clear.
233	    // lastOpacity now holds this call's opacity for every tile read below.
234	    const any=fogVertexAlphas(triangles,topology,lastOpacity,visible,explored,alphas);
235	    for(let v=0;v<alphas.length;v++){const alpha=alphas[v];fogUVs[v*2]=alpha===0?0:(alpha+.75)/256;fogUVs[v*2+1]=.5}
236	    fogNeeded=any;fog.visible=shown&&any;fogGeometry.attributes.aUV.buffer.update();
237	   };
238	   setFog([],[]);
239	   return {mesh,fog,triangles,depth:first.depth,bounds,setFog,setVisible(visible:boolean){shown=visible;mesh.visible=visible;fog.visible=visible&&fogNeeded},dispose(){geometry.destroy();fogGeometry.destroy();mesh.destroy();fog.destroy()}};
240	  });
241	 }
242	 /** Only after all raised fragments have been detached/disposed. */
243	 disposeSurfaceResources(){for(const texture of this.faceTextures.values())texture.destroy(true);this.faceTextures.clear();this.fogRamp?.destroy(true);this.fogRamp=undefined}
244	 private roadEdges(ctx:CanvasRenderingContext2D,x:number,y:number){
245	  const image=this.patterns.get('road_asphalt_decal');if(!image)return;
246	  for(const [dx,dy,angle] of [[0,-1,Math.PI],[1,0,-Math.PI/2],[0,1,0],[-1,0,Math.PI/2]]){
247	   const next=terrainAt(this.map,x+dx,y+dy);if(!['open','rubble','cover','ramp'].includes(next))continue;
248	   // The painted shoulder remains within the road tile, never suggesting that
249	   // adjacent impassable ground is traversable. Global phase avoids edge seams.
250	   const phase=((dx?y:x)%4+4)%4;
251	   ctx.save();ctx.translate(x+.5,y+.5);ctx.rotate(angle);ctx.drawImage(image,phase*image.naturalWidth/4,0,image.naturalWidth/4,image.naturalHeight,-.5,.20,1,.3);ctx.restore();
252	  }
253	 }
254	 private fillMaterial(ctx:CanvasRenderingContext2D,m:Material,x:number,y:number,size:number){
255	  const img=this.patterns.get(m);
256	  if(img){const pattern=ctx.createPattern(img,'repeat')!;pattern.setTransform(new DOMMatrix([1/128,0,0,1/128,0,0]));ctx.fillStyle=pattern}
257	  else ctx.fillStyle=FLAT[m];
258	  ctx.fillRect(x,y,size,size);
259	 }
260	 /** Minimap colour per tile, from the same materials. */
261	 static minimapColor(map:GameMap,x:number,y:number){
262	  const t=terrainAt(map,x,y),h=heightAt(map,x,y);
263	  const [r,g,b]=MINIMAP_BASE[t]??MINIMAP_BASE.open;const k=1+h*0.07;return [Math.min(255,r*k)|0,Math.min(255,g*k)|0,Math.min(255,b*k)|0] as const;
264	 }
265	}
