1	// work/renderer-performance-v1/baseline/client/src/render/terrain.ts
2	import { Texture, Mesh, MeshGeometry } from "pixi.js";
3	
4	// work/renderer-performance-v1/baseline/client/src/render/iso.ts
5	var HALF_W = 32;
6	var HALF_H = 16;
7	var LEVEL_PX = 10;
8	function toScreen(xMt, yMt) {
9	  const x = xMt / 1e3, y = yMt / 1e3;
10	  return { x: (x - y) * HALF_W, y: (x + y) * HALF_H };
11	}
12	function toWorld(sx, sy) {
13	  const a = sx / HALF_W, b = sy / HALF_H;
14	  return { x: (a + b) / 2 * 1e3, y: (b - a) / 2 * 1e3 };
15	}
16	
17	// work/renderer-performance-v1/baseline/client/src/render/terrain-surface.ts
18	var EPS = 1e-7;
19	var clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
20	var blocked = (terrain) => terrain === "cliff" || terrain === "water" || terrain === "blocked";
21	var mix = (a, b, t) => ({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, height: a.height + (b.height - a.height) * t });
22	function projectSurfaceVertex(vertex) {
23	  const p = toScreen(vertex.x, vertex.y);
24	  return { x: p.x, y: p.y - vertex.height * LEVEL_PX };
