}
const disk=(w:number,h:number,cx:number,cy:number,r:number)=>Array.from({length:w*h},(_,i)=>{const dx=i%w-cx,dy=Math.floor(i/w)-cy;return r>=0&&dx*dx+dy*dy<=r*r});

