   for(const key of ['fogTiles','fogPoints','fogPointStart','fogPointSlots','fogFanCorners'] as const)assert.deepEqual(candidate[key],frozen[key]);
   const deps=new Set(candidate.fogTiles);
   for(const t of triangles){
