    for(const [dx,dy] of CARDINAL){const nx=x+dx,ny=y+dy;if(nx>=0&&ny>=0&&nx<w&&ny<h)assert(deps.has(ny*w+nx),`${t.id}: cardinal ${nx},${ny} missing`)}
