  const p=[.2,.45,.7,.9][round%4],visible=Array.from({length:w*h},()=>rand()<p),explored=visible.map(v=>v||rand()<.5);
  fills+=checkAll(evaluate(prepared,visible,explored),w,h,visible,explored,`round ${round}`);
